from _h import case, step, G
C = []

C.append(case("htn", "Hypertension, including secondary hypertension", "cardiology", "The blood pressure that wouldn't come down",
 "Mrs Jade Thomas, 52 · teaching assistant · referred by the practice nurse",
 "“The nurse says my blood pressure is still high. I'm already on three tablets. I don't know what else I can do.”",
 [G("Which tablets, and does she take them?", "Amlodipine 10 mg, ramipril 10 mg, indapamide 2.5 mg. Her pharmacy record shows regular collection; she uses a dosette box.", 1, "On A + C + D, adherent"),
  G("Home BP readings", "Average of 7 days, twice daily: 152/94.", 1, "Home average 152/94"),
  G("Bloods from last week", "Na⁺ 139, K⁺ 4.0, creatinine 74, eGFR over 90. HbA1c 39.", 1, "K⁺ 4.0"),
  G("Any over-the-counter medicines?", "Ibuprofen now and then for her knee; no decongestants.", 0, "Occasional ibuprofen"),
  G("Urine dipstick and ACR", "No blood; ACR 1.8.", 0, "Urine normal"),
  G("Family history", "Mother had a stroke at 70.", 0, "Mother: stroke at 70")],
 [step("What does she have?", ["White-coat hypertension", "Resistant hypertension", "Accelerated hypertension", "Stage 1 hypertension, controlled", "Secondary hypertension from ramipril"], 1,
   "Resistant hypertension: BP not controlled on an ACE inhibitor, a calcium-channel blocker and a thiazide-like diuretic, with adherence confirmed and home readings above target.",
   ["Home readings are also high, so this isn't white-coat.", "", "No severe range or papilloedema.", "Her home target is below 135/85.", "ACE inhibitors don't cause hypertension."],
   "A 52-year-old woman takes amlodipine, ramipril and indapamide reliably. Her home BP average is 152/94. What is the diagnosis?"),
  step("Her potassium is 4.0. What is the most appropriate next drug?", ["Losartan", "Bisoprolol", "Doxazosin", "Low-dose spironolactone", "Furosemide"], 3,
   "NICE NG136 step 4: if K⁺ is 4.5 or less, add low-dose spironolactone; if higher, an alpha-blocker or beta-blocker. Check U&E within a month.",
   ["Never combine an ACE inhibitor with an ARB.", "Used when K⁺ is above 4.5.", "Used when K⁺ is above 4.5, or if spironolactone isn't tolerated.", "", "Loop diuretics aren't part of the hypertension ladder."],
   "A woman with resistant hypertension on A + C + D has a potassium of 4.0. What is the next drug?",
   bad={0: "Two weeks later her potassium is 6.1 and her creatinine has jumped. ACE inhibitor plus ARB is a dangerous combination."}, good="Six weeks later her home average is 133/82."),
  step("Four weeks after starting it, what must be checked?", ["Lipids", "U&E for potassium and renal function", "LFTs", "TFTs", "Nothing until her annual review"], 1,
   "Spironolactone with an ACE inhibitor can cause hyperkalaemia and kidney injury: check U&E within a month of starting, then regularly.",
   ["Not affected by spironolactone.", "", "Not the main risk.", "Not relevant.", "Too late: hyperkalaemia can develop within weeks."],
   "A patient on ramipril has just started spironolactone. What monitoring is needed in the first month?")],
 "../cardiology/hypertension.html",
 ["Confirm adherence and home readings before calling it resistant", "Step 4: K⁺ 4.5 or less → spironolactone; above 4.5 → alpha- or beta-blocker", "Never ACE inhibitor + ARB", "U&E within a month of spironolactone", "Uncontrolled on 4 drugs → specialist"]))

C.append(case("qrisk", "QRISK, lipids and statins", "cardiology", "The health check result",
 "Mr Daniel Okafor, 56 · bus depot manager · non-smoker",
 "“The health check lady said my heart risk is ‘amber’. Do I need a statin?”",
 [G("QRISK3 score", "15% over 10 years.", 1, "QRISK3 15%"),
  G("Cholesterol results", "Total 6.1, HDL 1.1, non-HDL 5.0 mmol/L.", 1, "Non-HDL 5.0"),
  G("Medical history", "No heart disease, stroke, diabetes or kidney disease.", 1, "No CVD"),
  G("ALT and TSH", "ALT 28, TSH 1.9.", 0, "ALT, TSH normal"),
  G("What does he already do?", "Walks the dog daily, eats takeaways twice a week, drinks 18 units a week.", 0, "18 units/week"),
  G("Family history", "Father had angina at 72.", 0, "Father: angina at 72")],
 [step("What does NICE recommend?", ["Atorvastatin 80 mg", "No statin until QRISK3 is 20%", "Atorvastatin 20 mg, after discussing risks and benefits, alongside lifestyle advice", "Ezetimibe first", "Simvastatin 40 mg"], 2,
   "Primary prevention with QRISK3 of 10% or more: offer atorvastatin 20 mg after a shared decision, with lifestyle advice.",
   ["That's the secondary-prevention dose.", "The threshold is 10% (NICE NG238).", "", "Ezetimibe isn't first line.", "Not the recommended statin."],
   "A 56-year-old with no CVD has a QRISK3 of 15%. What does NICE recommend?"),
  step("He starts atorvastatin 20 mg. When and how do you judge success?", ["Recheck lipids in a year; aim for total cholesterol under 5", "At 2–3 months, aim for a fall in non-HDL of more than 40%", "At 6 weeks, aim for LDL under 1.8", "No need to recheck if he feels well", "At 2–3 months, aim for HDL over 1.5"], 1,
   "Recheck lipids and ALT at 2–3 months; the target is a non-HDL cholesterol fall of more than 40% from baseline.",
   ["Too late, and the wrong target.", "", "Not NICE's primary-prevention target.", "Monitoring is needed.", "HDL isn't the target."],
   "A man starts atorvastatin 20 mg for primary prevention. What is the target at the 3-month review?"),
  step("At 3 months his ALT is 75 (upper limit 40). He feels well. What next?", ["Stop the statin", "Continue and recheck", "Halve the dose and recheck in a week", "Switch to rosuvastatin", "Refer to hepatology"], 1,
   "ALT under 3 times the upper limit: continue the statin and recheck. Stop only at 3 times or more.",
   ["Not needed: under 3 times the upper limit.", "", "No need to reduce at this level.", "Switching isn't needed.", "Not indicated."],
   "On atorvastatin, a man's ALT rises to 75 (upper limit 40). What is the appropriate action?")],
 "../cardiology/qrisk-lipids-statins.html",
 ["QRISK3 10% or more: atorvastatin 20 mg (primary prevention)", "CVD: atorvastatin 80 mg, no QRISK", "At 2–3 months: aim for non-HDL fall over 40%", "ALT: stop only at 3× the upper limit"]))

C.append(case("ecg", "ECG interpretation in primary care", "cardiology", "The ECG left in the tray",
 "Mrs Rosa Bell, 74 · lives alone · the HCA left her ECG in your tray",
 "The healthcare assistant's note: “Routine ECG before review. She says she feels fine.”",
 [G("Rate and rhythm", "Regular, rate 75.", 0, "Regular, 75"),
  G("T waves and QRS", "Tall, peaked T waves; QRS slightly broad at 125 ms; P waves flattened.", 1, "Peaked T, broad QRS"),
  G("Her medicines", "Ramipril 10 mg, spironolactone 25 mg, and trimethoprim started 3 days ago for a UTI.", 1, "Ramipril + spironolactone + trimethoprim"),
  G("Recent bloods", "Six months ago: K⁺ 5.1, eGFR 48.", 1, "eGFR 48; K⁺ was 5.1"),
  G("Symptoms now", "Some weakness in her legs today.", 0, "Leg weakness"),
  G("QTc", "QTc 430 ms.", 0, "QTc normal")],
 [step("What do the ECG and history suggest?", ["Hypokalaemia", "Hyperkalaemia", "Digoxin effect", "Pericarditis", "Normal variant"], 1,
   "Peaked T waves, flat P waves and a widening QRS suggest hyperkalaemia, here from an ACE inhibitor, spironolactone and trimethoprim with reduced kidney function.",
   ["Hypokalaemia gives flat T waves and U waves.", "", "Digoxin gives reverse-tick ST depression.", "Pericarditis gives saddle ST elevation.", "These changes are never normal."],
   "A 74-year-old on ramipril, spironolactone and trimethoprim has peaked T waves and a broadening QRS. What is the most likely cause?"),
  step("What is the most appropriate action?", ["Repeat U&E tomorrow", "Stop spironolactone and recheck in a week", "Same-day emergency admission", "Low-potassium diet leaflet", "Start a loop diuretic and review"], 2,
   "Hyperkalaemia with ECG changes is an emergency needing cardiac monitoring and treatment (calcium, insulin–glucose). Stop the culprit drugs.",
   ["Too slow with ECG changes: risk of arrest.", "Too slow on its own.", "", "Not appropriate in an emergency.", "Not adequate treatment."],
   "A patient has suspected hyperkalaemia with peaked T waves and a broad QRS on ECG. What is the most appropriate action?",
   bad={0: "That evening she collapses at home. The ambulance crew find a slow broad-complex rhythm; her potassium in hospital is 7.4.", 1: "Four days later she is found on the floor, weak and confused. Potassium 7.1."}, good="In hospital her potassium is 6.9; it comes down with calcium gluconate and insulin–glucose."),
  step("Which of her drugs is the commonly overlooked contributor?", ["Ramipril", "Spironolactone", "Trimethoprim", "Paracetamol", "Atorvastatin"], 2,
   "Trimethoprim reduces renal potassium excretion (an amiloride-like effect): a classic precipitant in people on ACE inhibitors or spironolactone.",
   ["A known cause, but not overlooked.", "A known cause, but not overlooked.", "", "Doesn't affect potassium.", "Doesn't affect potassium."],
   "Which antibiotic can raise potassium, especially in someone taking an ACE inhibitor?")],
 "../cardiology/ecg-interpretation.html",
 ["Peaked T → flat P → broad QRS = hyperkalaemia", "ECG changes or K⁺ 6.5+: emergency", "Trimethoprim raises potassium", "Ask: regular? P before every QRS?"]))

C.append(case("af", "Atrial fibrillation", "cardiology", "The irregular pulse at the flu clinic",
 "Mr Harold Price, 78 · retired joiner · flu jab today",
 "The nurse says: “His pulse felt irregular, so I've booked him in with you.”",
 [G("ECG", "Irregularly irregular narrow-complex rhythm, no P waves, rate 104.", 1, "AF, rate 104"),
  G("How does he feel?", "Fine. Perhaps more tired climbing stairs recently.", 0, "Mild fatigue"),
  G("When did it start?", "He doesn't know.", 1, "Onset unknown"),
  G("Medical history", "Hypertension and type 2 diabetes.", 1, "Hypertension, diabetes"),
  G("Bloods", "Creatinine 110, weight 72 kg; CrCl about 49. Hb 138. TSH normal.", 1, "CrCl 49"),
  G("BP and observations", "BP 142/84, SpO₂ 97%, no chest pain.", 0, "Stable")],
 [step("What is the most appropriate initial management?", ["Same-day admission for cardioversion", "Bisoprolol for rate control", "Amiodarone", "Digoxin first line", "No treatment: he feels fine"], 1,
   "Stable AF of unknown onset: rate control first line with a beta-blocker or rate-limiting calcium-channel blocker.",
   ["Only for onset under 48 hours or instability.", "", "Rhythm control is specialist-led.", "Digoxin alone is for sedentary people with non-paroxysmal AF.", "Rate and stroke risk still need treating."],
   "A stable 78-year-old has AF of unknown onset, rate 104. What is first-line management?"),
  step("What is his CHA₂DS₂-VASc score?", ["2", "3", "4", "5", "6"], 2,
   "Age 75+ (2) + hypertension (1) + diabetes (1) = 4.",
   ["Missed some points.", "Age 75 or over scores 2.", "", "He's male: no sex point.", "Too high."],
   "A 78-year-old man with AF, hypertension and type 2 diabetes. What is his CHA₂DS₂-VASc score?"),
  step("Which anticoagulant and dose?", ["Aspirin 75 mg", "Apixaban 2.5 mg twice daily", "Apixaban 5 mg twice daily", "Warfarin only", "No anticoagulation: age over 75"], 2,
   "Apixaban 5 mg twice daily. The lower dose needs 2 of: age 80+, weight 60 kg or less, creatinine 133 or more (or CrCl 15–29). He has none.",
   ["Aspirin isn't used for stroke prevention in AF.", "He doesn't meet the dose-reduction criteria.", "", "A DOAC is first line unless contraindicated.", "Age is a reason to anticoagulate, not to withhold."],
   "A 78-year-old man with AF weighs 72 kg, creatinine 110. What apixaban dose?",
   bad={4: "Five months later he's admitted with a left hemiparesis and dysphasia: a cardioembolic stroke.", 0: "Four months later he has a disabling stroke. Aspirin doesn't prevent AF strokes."})],
 "../cardiology/atrial-fibrillation.html",
 ["Stable, unknown onset: rate control first", "CHA₂DS₂-VASc 2+: offer a DOAC", "Apixaban 2.5 mg needs 2 of: 80+, ≤60 kg, creatinine ≥133", "Never aspirin for AF stroke prevention"]))

C.append(case("acs", "Acute coronary syndrome and myocardial infarction", "cardiology", "The indigestion that wasn't",
 "Mrs Linda Shaw, 69 · type 2 diabetes · phoned for an urgent appointment",
 "“I've had indigestion since lunchtime. It's not going away and I feel a bit sick.”",
 [G("When did it start?", "About 2 hours ago, at rest, and it's still there.", 1, "Ongoing, 2 hours"),
  G("What is it like?", "A heavy pressure in the upper chest, into her jaw.", 1, "Heavy pressure to jaw"),
  G("Observations", "Pale and clammy. BP 136/82, pulse 98, SpO₂ 96%.", 1, "Clammy"),
  G("ECG (if quick)", "ST depression in V4–V6.", 0, "ST depression laterally"),
  G("Has she had antacids?", "Two doses of Gaviscon; no help.", 0, "No relief from antacid"),
  G("Allergies", "None.", 0, "No allergies")],
 [step("What is the most appropriate immediate action?", ["Same-day troponin as an outpatient", "Rapid-access chest pain clinic", "Call 999 and give aspirin 300 mg", "Omeprazole and review tomorrow", "GTN and repeat the ECG in an hour"], 2,
   "Current chest pain suspected to be ACS: 999, aspirin 300 mg chewed. Atypical presentations are common in diabetes and older women.",
   ["She has ongoing pain: emergency.", "For stable, exertional chest pain only.", "", "Dangerous anchoring on 'indigestion'.", "Delays emergency transfer."],
   "A 69-year-old woman with diabetes has 2 hours of ongoing heavy upper chest discomfort and is clammy. What is the immediate action?",
   bad={3: "She is brought to the emergency department that night by her husband after collapsing: troponin markedly raised, NSTEMI with heart failure.", 4: "While you wait, she becomes grey and breathless. The delay matters."}),
  step("In hospital she has an NSTEMI and a stent. Which antiplatelet plan will she go home on?", ["Aspirin alone", "Aspirin lifelong plus ticagrelor for 12 months", "Clopidogrel alone for 1 month", "Warfarin", "Ticagrelor lifelong"], 1,
   "Dual antiplatelet therapy: aspirin 75 mg lifelong plus a second antiplatelet (usually ticagrelor) for 12 months.",
   ["DAPT is needed after ACS.", "", "Too short, and single therapy.", "Not an antiplatelet; no indication.", "The second agent stops at 12 months."],
   "After an NSTEMI with PCI, what antiplatelet regimen is usual?"),
  step("She asks about omeprazole for her stomach while on clopidogrel (switched due to bleeding risk). What do you advise?", ["Omeprazole is ideal", "Avoid PPIs completely", "Use lansoprazole rather than omeprazole", "Use ranitidine", "Stop clopidogrel"], 2,
   "Omeprazole and esomeprazole reduce clopidogrel's effect; lansoprazole is preferred.",
   ["It interacts with clopidogrel.", "A PPI is often wise for gastroprotection.", "", "Ranitidine has been withdrawn.", "Never stop antiplatelets without cardiology advice."],
   "Which proton pump inhibitor is preferred with clopidogrel?")],
 "../cardiology/acute-coronary-syndrome.html",
 ["Ongoing pain: 999 + aspirin 300 mg; don't wait for an ECG", "Diabetes, women, older people: atypical pain", "DAPT 12 months, aspirin lifelong", "Clopidogrel: lansoprazole, not omeprazole"]))

C.append(case("hf", "Heart failure", "cardiology", "Breathless at night",
 "Mr Frank Ellis, 74 · ex-smoker · previous MI 6 years ago",
 "“I can't lie flat any more. I've been sleeping in the chair for a week, and my ankles are like balloons.”",
 [G("Breathlessness", "On walking 50 yards; wakes gasping at night.", 1, "Orthopnoea, PND"),
  G("Examination", "JVP raised, bibasal crackles, pitting oedema to the knees. SpO₂ 95% at rest.", 1, "Fluid overloaded, SpO₂ 95%"),
  G("NT-proBNP", "3,400 ng/L.", 1, "NT-proBNP 3,400"),
  G("Medicines", "Aspirin, atorvastatin, and ibuprofen for his back.", 1, "Taking ibuprofen"),
  G("ECG", "Sinus rhythm, old Q waves inferiorly.", 0, "Old inferior MI"),
  G("Weight", "Up 4 kg in 2 weeks.", 0, "Weight +4 kg")],
 [step("He is stable at rest. What is the referral?", ["Routine echo", "Specialist assessment and echo within 2 weeks", "Within 6 weeks", "999", "Repeat NT-proBNP in a month"], 1,
   "NT-proBNP over 2,000 ng/L: specialist assessment and echo within 2 weeks. Start a loop diuretic for congestion meanwhile.",
   ["Too slow.", "", "That's for 400–2,000.", "Not needed: stable, SpO₂ 95%.", "Delays diagnosis."],
   "A 74-year-old with suspected heart failure has an NT-proBNP of 3,400 ng/L and is stable. What is the referral?"),
  step("Which medicine should be stopped now?", ["Atorvastatin", "Aspirin", "Ibuprofen", "None", "All of them"], 2,
   "NSAIDs cause fluid retention and kidney injury, worsening heart failure.",
   ["Needed after MI.", "Needed after MI.", "", "The NSAID is harmful.", "Secondary prevention must continue."],
   "A man with new heart failure is taking ibuprofen, aspirin and atorvastatin. Which should be stopped?"),
  step("Echo: LVEF 30%. What does NICE (2025) say about drug treatment?", ["ACE inhibitor alone first, then add others one at a time over a year", "Offer all four: ACE inhibitor, beta-blocker, MRA and SGLT2 inhibitor", "Digoxin and furosemide only", "Amlodipine and a diuretic", "Ivabradine first"], 1,
   "HFrEF (EF 40% or less): offer all four pillars, titrated, plus a loop diuretic for congestion.",
   ["NICE now recommends all four.", "", "Digoxin is add-on only.", "Amlodipine doesn't improve prognosis.", "Specialist add-on in selected people."],
   "A man has heart failure with an LVEF of 30%. What drug treatment does NICE (2025) recommend?")],
 "../cardiology/heart-failure.html",
 ["NT-proBNP over 2,000: within 2 weeks; 400–2,000: 6 weeks", "Stop NSAIDs", "HFrEF: all four pillars", "Daily weights: 1.5–2 kg in 2–3 days → call"]))

C.append(case("vte", "Venous thromboembolism: DVT and PE", "cardiology", "The swollen calf after the flight",
 "Ms Priya Nair, 38 · solicitor · flew back from Sydney 5 days ago",
 "“My left calf has been aching for two days and it's swollen. I thought I'd pulled something.”",
 [G("Examination", "Left calf 4 cm bigger than right, pitting oedema, tender along the deep veins.", 1, "Calf +4 cm, tender veins"),
  G("Medicines", "Combined oral contraceptive pill.", 1, "On the combined pill"),
  G("Chest symptoms", "None; SpO₂ 99%, pulse 82.", 0, "No PE features"),
  G("Previous clots", "None.", 0, "No previous VTE"),
  G("Any injury?", "No.", 0, "No trauma"),
  G("Is a scan available today?", "The DVT clinic can scan her tomorrow morning, not within 4 hours.", 1, "Scan tomorrow")],
 [step("Her 2-level Wells score is 3 (calf swelling, pitting oedema, tender deep veins). What is the plan?", ["D-dimer only and review", "Proximal ultrasound; as it can't be within 4 hours, D-dimer and interim anticoagulation", "Aspirin and stockings", "CTPA", "Reassure: muscle strain"], 1,
   "DVT likely (Wells 2 or more): ultrasound within 4 hours; if not possible, take a D-dimer, start interim anticoagulation, and scan within 24 hours.",
   ["Likely DVT needs imaging.", "", "Not treatment for DVT.", "No PE features.", "Signs are typical of DVT."],
   "A woman has a Wells score of 3 for DVT and the scan isn't available for 18 hours. What is the plan?",
   bad={4: "Three days later she becomes suddenly breathless at work: pulmonary embolism."}),
  step("The scan confirms a proximal DVT. Which treatment?", ["LMWH for 6 months", "Apixaban 10 mg twice daily for 7 days, then 5 mg twice daily", "Warfarin alone", "Aspirin", "Compression stockings only"], 1,
   "Apixaban or rivaroxaban is first line; apixaban starts at 10 mg twice daily for 7 days.",
   ["For pregnancy or certain cancers.", "", "Needs LMWH cover first; not first line.", "Not an anticoagulant for VTE.", "Not treatment."],
   "A 38-year-old has a confirmed proximal DVT. What is first-line treatment?"),
  step("What about her pill, and how long to treat?", ["Continue the pill; treat for 6 weeks", "Stop the combined pill; treat for 3 months (provoked)", "Continue the pill; lifelong anticoagulation", "Stop the pill; lifelong anticoagulation", "Switch to HRT"], 1,
   "Stop oestrogen-containing contraception and use a non-hormonal or progestogen-only method. A provoked clot (flight, oestrogen) is treated for 3 months.",
   ["Oestrogen must stop; 6 weeks is too short.", "", "Oestrogen must stop.", "Lifelong is for unprovoked or recurrent cases.", "HRT also contains oestrogen."],
   "A woman on the combined pill has a DVT after a long-haul flight. What contraception and duration advice?")],
 "../cardiology/vte.html",
 ["Wells 2+: scan within 4 hours, or D-dimer + interim anticoagulation", "Apixaban 10 mg bd for 7 days", "Provoked: 3 months", "Stop oestrogen"]))

C.append(case("tia", "TIA and stroke recognition", "cardiology", "Ten minutes of nothing",
 "Mr Kevin Doyle, 66 · taxi driver · walks in at the end of morning surgery",
 "“This morning my right hand went useless and I couldn't get my words out. Ten minutes, then it went. I'm fine now, honest.”",
 [G("Symptoms now", "None. Full power, speech normal.", 1, "Fully resolved"),
  G("Glucose", "6.2 mmol/L.", 1, "Glucose normal"),
  G("Pulse", "Irregularly irregular, 88.", 1, "Irregular pulse"),
  G("Medicines", "Amlodipine; no anticoagulant.", 0, "No anticoagulant"),
  G("BP", "158/90.", 0, "BP 158/90"),
  G("Headache or visual aura?", "None.", 0, "No migraine features")],
 [step("What is the most appropriate immediate management?", ["999 to the stroke unit", "Aspirin 300 mg now and refer to be seen within 24 hours", "Calculate ABCD2 and refer within 7 days if low", "CT head next week", "Reassure: symptoms have gone"], 1,
   "Suspected TIA, symptoms resolved, not on an anticoagulant: aspirin 300 mg immediately and refer to be seen within 24 hours of onset (NICE NG128). ABCD2 isn't used.",
   ["Symptoms have resolved; it's a TIA pathway.", "", "ABCD2 is no longer used.", "Imaging isn't the first step.", "High early stroke risk."],
   "A man had 10 minutes of right hand weakness and dysphasia, now resolved. He takes no anticoagulant. What is the management?",
   bad={4: "Two days later he has a disabling left hemisphere stroke."}),
  step("ECG in clinic confirms AF. Imaging shows no bleed. What long-term antithrombotic?", ["Clopidogrel 75 mg", "Aspirin and dipyridamole", "A DOAC such as apixaban", "Aspirin and clopidogrel for 21 days", "No treatment"], 2,
   "Cardioembolic TIA with AF needs anticoagulation instead of antiplatelets; after a TIA it can start once haemorrhage is excluded.",
   ["For TIA in sinus rhythm.", "An alternative antiplatelet regimen, not for AF.", "", "For high-risk TIA in sinus rhythm.", "He needs stroke prevention."],
   "A TIA patient is found to be in AF; haemorrhage is excluded. What long-term antithrombotic?"),
  step("He asks about driving his taxi. What applies?", ["Group 1: 1 month off, no need to notify", "Taxi licences usually follow Group 2 standards: tell the licensing authority; Group 2 needs 1 year off", "No restriction", "1 week off", "6 months off for any licence"], 1,
   "Taxi drivers are licensed by the council, which usually applies Group 2 standards. For his car licence (Group 1): 1 month off; Group 2: 1 year off and notify.",
   ["True for his private car, but not for taxi work.", "", "Driving is restricted after a TIA.", "Too short.", "Not the TIA rule."],
   "A taxi driver has had a TIA. What driving standard usually applies to his work?")],
 "../cardiology/tia-stroke.html",
 ["TIA: aspirin 300 mg, seen within 24 hours, no ABCD2", "Symptoms now: 999", "Check glucose and pulse", "AF: anticoagulate instead of antiplatelets", "Group 1: 1 month; Group 2: 1 year"]))

C.append(case("angina", "Stable angina", "cardiology", "Tight on the hill",
 "Mrs Sandra Hughes, 63 · school cook · smoker",
 "“When I walk up the hill to work my chest goes tight. If I stop for a couple of minutes it goes.”",
 [G("Character and site", "Tight band across the chest.", 1, "Constricting"),
  G("Trigger", "Only walking uphill or rushing.", 1, "Exertional"),
  G("Relief", "Goes within 3 minutes of stopping.", 1, "Relieved by rest"),
  G("Any rest pain or worsening?", "No. Same for 2 months.", 1, "Stable pattern"),
  G("ECG", "Normal.", 0, "Normal ECG"),
  G("Bloods", "Hb 132, TSH normal, HbA1c 41.", 0, "No anaemia")],
 [step("How is her pain classified, and what test should she have?", ["Non-anginal; reassure", "Atypical angina; exercise ECG", "Typical angina; CT coronary angiography", "Typical angina; same-day troponin", "Unstable angina; 999"], 2,
   "Three features (constricting, exertional, relieved by rest within 5 minutes): typical angina. NICE: 64-slice CTCA first.",
   ["She has all three features.", "Exercise ECG is no longer used to diagnose angina.", "", "Stable pattern: not ACS.", "No rest pain or crescendo."],
   "A woman has constricting chest pain on exertion relieved by rest in 3 minutes, stable for 2 months. Classification and first test?"),
  step("While waiting, what treatment?", ["GTN spray only", "GTN spray, plus a beta-blocker or CCB, aspirin and a statin", "Nicorandil first", "Isosorbide mononitrate only", "Nothing until CTCA"], 1,
   "Short-acting nitrate for everyone, a beta-blocker or calcium-channel blocker first line, plus secondary prevention (aspirin, statin). Stop smoking.",
   ["Needs anti-anginal and secondary prevention too.", "", "Second line.", "Second line.", "Treat symptoms and risk now."],
   "A woman with suspected stable angina awaits CTCA. What treatment should she have meanwhile?"),
  step("On bisoprolol she still has symptoms. Which drug do you add?", ["Verapamil", "Amlodipine", "Diltiazem", "A second beta-blocker", "Digoxin"], 1,
   "Combine a beta-blocker with a dihydropyridine CCB (amlodipine, MR nifedipine). Verapamil with a beta-blocker risks heart block.",
   ["Dangerous with a beta-blocker.", "", "Rate-limiting: avoid with a beta-blocker.", "Never two beta-blockers.", "Not an anti-anginal."],
   "Angina isn't controlled on bisoprolol. Which calcium-channel blocker should be added?",
   bad={0: "A week later she's brought in after collapsing: pulse 32, complete heart block. Verapamil plus a beta-blocker."})],
 "../cardiology/stable-angina.html",
 ["3 features typical, 2 atypical", "CTCA first", "BB or CCB + GTN; amlodipine with a BB", "Not controlled on two: refer"]))
